Clase RangoDeEdad
    Privado Definir minimo Como Entero;
    Privado Definir maximo Como Entero;

    Metodo Constructor(unMinimo Como Entero, unMaximo Como Entero)
        Este.minimo <- unMinimo;
        Este.maximo <- unMaximo;
    FinMetodo

    Publico Metodo EstaEnRango(edad Como Entero) Como Entero
        Si edad >= Este.minimo Y edad <= Este.maximo Entonces
            Retornar 1;
        SiNo
            Retornar 0;
        FinSi
    FinMetodo
FinClase

Proceso ValidarEdad
    Definir minimo Como Entero;
    Definir maximo Como Entero;
    Definir edad Como Entero;
    Definir rango Como RangoDeEdad;
    Leer minimo;
    Leer maximo;
    Leer edad;
    rango <- Nuevo RangoDeEdad(minimo, maximo);
    Escribir rango.EstaEnRango(edad);
FinProceso
